"use client"

import * as React from "react"
import { ChevronRightIcon } from "lucide-react"
import { cn } from "cn"
import {
  Button,
  Tree as TreePrimitive,
  TreeItem as TreeItemPrimitive,
  TreeItemContent,
  type TreeItemProps,
  type TreeProps,
} from "react-aria-components"

/** React Aria Tree: arrow-key navigation, typeahead, selection and expansion built in. */
function Tree<T extends object>({ className, ...props }: Omit<TreeProps<T>, "className"> & { className?: string }) {
  return (
    <TreePrimitive
      data-slot="tree"
      className={cn("flex w-full flex-col gap-px text-sm outline-none", className)}
      {...props}
    />
  )
}

/** One node. Nested TreeItem children make it expandable. */
function TreeItem({
  className,
  title,
  icon,
  children,
  textValue,
  ...props
}: Omit<TreeItemProps, "className" | "children"> & {
  className?: string
  title?: React.ReactNode
  icon?: React.ReactNode
  children?: React.ReactNode
}) {
  return (
    <TreeItemPrimitive
      data-slot="tree-item"
      textValue={textValue}
      className={cn(
        "group/tree-item rounded-md text-foreground outline-none data-[disabled]:opacity-50 data-[focus-visible]:ring-3 data-[focus-visible]:ring-ring/50 data-[hovered]:bg-muted data-[selected]:bg-muted data-[selected]:font-medium",
        className
      )}
      {...props}
    >
      <TreeItemContent>
        {({ hasChildItems, isExpanded, level }) => (
          <div
            className="flex h-8 items-center gap-1.5 pr-2"
            style={{ paddingInlineStart: `calc(${level - 1} * var(--spacing) * 4 + var(--spacing) * 1)` }}
          >
            {hasChildItems ? (
              <Button
                slot="chevron"
                className="flex size-5 shrink-0 items-center justify-center rounded-sm text-muted-foreground outline-none data-[focus-visible]:ring-3 data-[focus-visible]:ring-ring/50"
              >
                <ChevronRightIcon className={cn("size-3.5 transition-transform", isExpanded && "rotate-90")} />
              </Button>
            ) : (
              <span aria-hidden="true" className="size-5 shrink-0" />
            )}
            {icon && <span className="flex shrink-0 text-muted-foreground [&_svg:not([class*='size-'])]:size-4">{icon}</span>}
            <span className="truncate">{title ?? textValue}</span>
          </div>
        )}
      </TreeItemContent>
      {children}
    </TreeItemPrimitive>
  )
}

export { Tree, TreeItem }
